        mae = runs[0].summary.get('test/overall/mae_surf_p', None)
        if mae:
            best[agent] = mae
for agent, mae in sorted(best.items(), key=lambda x: x[1]):
    marker = " <-- ME" if agent == 'edward' else ""
    print(f'{agent:15s}: {mae:.2f}{marker}')
